//! Declaration digests are generated by the client build; no manually copied signatures.
// @ref LLP 3000.037.000#8-wave-32-builder-reading-and-waiting-tok1 — on-demand module shapes replace d.ts greps.
pub fn render(module: &str, full: bool) -> Result<String, String> {
    if matches!(module, "client" | "react" | "auth" | "generated") {
        let cwd = std::env::current_dir().map_err(|e| e.to_string())?;
        if let Some(project) = crate::project::Project::locate(&cwd) {
            let bound = project.compile().map_err(|e| e.to_string())?;
            if bound.diagnostics.is_empty() {
                let digest = if module == "generated" {
                    String::new()
                } else {
                    generic(module, false)?
                };
                return Ok(usage(&bound, module, &digest));
            }
            if module == "generated" {
                return Err(
                    "guide api generated: run snapback4 check to repair the schema first".into(),
                );
            }
            return Ok(format!(
                "App schema does not bind; run snapback4 check. Generic signatures follow.\n\n{}",
                generic(module, full)?
            ));
        }
    }
    if module == "generated" {
        return Err(
            "guide api generated: run in your project with a bound snapback/*.q schema".into(),
        );
    }
    generic(module, full)
}

pub fn generic(module: &str, full: bool) -> Result<String, String> {
    let rendered: Result<String, String> = match module {
        "app" if full => Ok(include_str!("../../snapback4-lang/src/guide/api_app_full.md").into()),
        "app" => Ok(include_str!("../../snapback4-lang/src/guide/api_app.md").into()),
        "witness" if full => {
            Ok(include_str!("../../snapback4-lang/src/guide/api_witness_full.md").into())
        }
        "witness" => Ok(include_str!("../../snapback4-lang/src/guide/api_witness.md").into()),
        "react" if full => {
            Ok(include_str!("../../snapback4-lang/src/guide/api_react_full.md").into())
        }
        "react" => Ok(include_str!("../../snapback4-lang/src/guide/api_react.md").into()),
        "proof" if full => {
            Ok(include_str!("../../snapback4-lang/src/guide/proof_api_reference.md").into())
        }
        "proof" => Ok(include_str!("../../snapback4-lang/src/guide/api_proof.md").into()),
        "client" if full => {
            Ok(include_str!("../../snapback4-lang/src/guide/api_client_full.md").into())
        }
        "client" => Ok(include_str!("../../snapback4-lang/src/guide/api_client.md").into()),
        "auth" if full => {
            Ok(include_str!("../../snapback4-lang/src/guide/api_auth_full.md").into())
        }
        "auth" => Ok(include_str!("../../snapback4-lang/src/guide/api_auth.md").into()),
        "generated" => Err("guide api generated has app usage only; use guide api client --generic for SDK signatures".into()),
        _ => {
            Err("usage: snapback4 guide api <app|react|proof|client|auth|witness|generated>".into())
        }
    };
    let raw = rendered?;
    // Full generated declaration sets are one declaration per line. Separate
    // their fences so a large module can page without splitting TypeScript.
    Ok(if full && raw.len() > snapback4_lang::guide::FULL_BYTES {
        let (intro, code) = raw
            .split_once("```ts\n")
            .ok_or("signature reference has no TypeScript fence")?;
        let (code, tail) = code
            .split_once("\n```")
            .ok_or("signature reference has no closing fence")?;
        format!(
            "{intro}{}\n{tail}",
            code.lines()
                .map(|line| format!("```ts\n{line}\n```\n\n"))
                .collect::<String>()
        )
    } else {
        raw
    })
}

// @ref LLP 3000.037.000#18-bounded-package-reference-and-wiring-lookups-tok6 — the first wiring lookup is the app packet, not a pointer to another read.
fn usage(bound: &snapback4_lang::Bound, module: &str, digest: &str) -> String {
    let packet = snapback4_lang::emit::usage::markdown(bound, false);
    let mut out = String::from(
        "# This app's client usage\n\nFrom the current bound snapback/*.q schema (Client usage packet); generated types: snapback/generated/api.ts. Edit the schema, never generated files.\n\n",
    );
    out.push_str("Browser/React: reuse app.client under AppProvider; it owns write admission. Hooks run at component/custom-hook top level; invoke writes in handlers. Plain Node/server: createClient({url, session}) from snapback4/client; bare browser clients refuse durable writes with E_ADMISSION. Signup grants no role; provision the signed-in principal with your authorized operation/operator. Roles are stored rows, never client options. Clients use this caller's credential. Service-only guards require server-side createClient({url,token}) with a minted service token; never expose it in a browser. Session lines quote caller guards, not a complete authorization analysis; row/field rules still apply.\n\n");
    if bound.schema.auth.password {
        out.push_str("```ts\n// Import your existing app from src/client.\nawait app.ready;\nconst signedIn = await app.auth.login(email, password);\nif (!signedIn.ok) throw new Error(signedIn.why.code);\n```\n\n");
    }
    if module != "auth" {
        out.push_str("Import api/Rows from your generated api.ts; ArgsOf/ResultOf/isReady from snapback4/contract. Hooks: snapback4/react. isReady(read) exposes data; denied.code explains denial. Pages: items/read/loadMore; query.next passes unchanged as the cursor until null. Writes: refusalOf(write) from snapback4/client returns failure; why is undefined unless failed. Sent.result can be absent on replay; pending is not committed. Actions/signals have their own union.\n\n");
        out.push_str("Uploads: await client.upload(bytes), check uploaded.ok, pass {id: uploaded.asset.id}. Documents: upload(bytes, {file:{type,name}}). Upload separately per column. Declared refusals below exclude infrastructure/auth/input/rule/meter/upload failures.\n\n");
        if let Some((_, rows)) = packet.split_once("Result row fields") {
            let rows = rows.split("\n## ").next().unwrap();
            out.push_str("Result row fields");
            out.push_str(rows);
            out.push('\n');
        }
    }
    for operation in packet.split("\n## ").skip(1) {
        let (heading, body) = operation.split_once('\n').unwrap();
        out.push_str(&format!("\n## {heading}\n\n"));
        let calls = body.split_once("```ts\n").unwrap().1;
        let path = calls
            .split("const operation = ")
            .nth(1)
            .unwrap()
            .split(";\n")
            .next()
            .unwrap();
        let header = body
            .split("```ts")
            .next()
            .unwrap()
            .trim()
            .replace(
                "Session: client uses this caller's credential; ",
                "Session: ",
            )
            .replace("typeof operation", &format!("typeof {path}"))
            .replace("Ops below", "Ops in snapback/generated/api.ts")
            .replace("Ops/Rows below", "Ops/Rows in snapback/generated/api.ts");
        if module == "auth" {
            for line in header.lines().filter(|line| {
                line.starts_with("Session:") || line.starts_with("Declared refusals:")
            }) {
                out.push_str(line);
                out.push('\n');
            }
        } else {
            out.push_str(&header);
            out.push_str("\n\n");
            // GEN1 classifies paged/Following/action/held calls. Reuse its exact paths.
            let hook = calls
                .split("return use")
                .nth(1)
                .map(|s| format!("use{}", s.split('(').next().unwrap()))
                .or_else(|| {
                    calls
                        .split("const op = ")
                        .nth(1)
                        .map(|s| s.split('(').next().unwrap().to_owned())
                })
                .unwrap();
            let method = calls
                .split("return client.")
                .nth(1)
                .unwrap()
                .split('(')
                .next()
                .unwrap();
            let react = if method == "query" {
                format!("{hook}({path}, args)")
            } else {
                format!("{hook}({path}) // call .run(args) in a handler")
            };
            if module != "client" {
                out.push_str(&format!("React: `{react}`. "));
            }
            if module != "react" {
                out.push_str(&format!("Plain: `client.{method}({path}, args)`. "));
            }
            if hook == "usePage" && module != "client" {
                out.push_str("React args omit c; the hook owns the cursor.");
            }
            out.push_str("\n");
        }
    }
    out.push_str("\nSDK declarations beyond this usage: guide api ");
    out.push_str(if module == "generated" {
        "client"
    } else {
        module
    });
    out.push_str(" --generic (use --full for its section index).\n");
    if !digest.is_empty() {
        // Calls, setup, upload placement and guards are covered. Keep complementary signatures.
        let names: &[&str] = match module {
            "react" => &[
                "ReadState",
                "ReadHookOptions",
                "PageHook",
                "WriteHook",
                "AssetState",
                "useClient",
                "useAuth",
                "AppProvider",
            ],
            "client" => &[
                "Read",
                "Ready",
                "Write",
                "Observed",
                "Session",
                "Cursor",
                "Refusal",
                "settleMutation",
            ],
            "auth" => &[
                "SignIn",
                "Session",
                "SignInOptions",
                "SessionStore",
                "restoreSession",
                "keepSession",
                "forgetSession",
                "logout",
                "logoutAll",
                "refreshSession",
                "narrowSession",
            ],
            _ => &[],
        };
        let signatures = digest
            .lines()
            .filter(|line| {
                names.iter().any(|name| {
                    [
                        "export function ",
                        "export type ",
                        "export interface ",
                        "export const ",
                    ]
                    .iter()
                    .any(|prefix| {
                        line.strip_prefix(prefix).is_some_and(|tail| {
                            tail.strip_prefix(name)
                                .is_some_and(|rest| rest.starts_with(['<', '(', ':', ' ', '=']))
                        })
                    })
                })
            })
            .collect::<Vec<_>>()
            .join("\n");
        if !signatures.is_empty() {
            out.push_str(&format!(
                "\n## Additional {module} signatures\n\n```ts\n{signatures}\n```\n"
            ));
        }
    }
    out
}
